// === Tab: Particle.pde ===
// let class for 2D space.
// let Brand, 22 march 2009.

class Particle 
{
  acc;
  vel;
  loc;
  mass;
  lim;
  isLimited;
  c;

  // Constructor
  constructor(a_, v_, l_, m_)
  {
    acc = a_.get();
    vel = v_.get();
    loc = l_.get();
    mass = m_;
    lim = 0;
    isLimited = false;
    c = color(255);
  }

  constructor(a_, v_, l_)
  {
    acc = a_.get();
    vel = v_.get();
    loc = l_.get();
    mass = 10;
    lim = 0;
    isLimited = false;
    c = color(255);
  }

  constructor(l_)
  {
    acc = new PVector();
    vel = new PVector();
    loc = l_.get();
    mass = 10;
    lim = 0;
    isLimited = false;
    c = color(255);
  }

  function run() 
  {
    update();
    render();
  }

  function update()
  {
    vel.add(acc);
    if (isLimited) vel.limit(lim);
    loc.add(vel);
  }

  function render()
  {
    drawStar(pg1, loc.x, loc.y);
  }

  function renderVector(v_, s_)
  {
    pushMatrix();
    translate(loc.x, loc.y);
    rotate(vel.heading2D());   

    let len = v_.mag()*s_; //get magnitude and scale

    line(0, 0, len, 0);
    line(len, 0, len-4, 2);
    line(len, 0, len-4, -2);
    popMatrix();
  }

  function setLimit(l_)
  {
    lim = l_;
    isLimited = true;
  }

  function addForce(v_) 
  {
    // force=mass*acc, added acc=force/mass
    let force = v_.get();
    force.div(mass);
    acc.add(force);
  }

  function setColor(c_) {
    c = c_;
  }
}


// === Tab: particles.pde ===
let p;
let numP = 51200;
let pg1;

function setup() {
  createCanvas(512, 512);
  colorMode(RGB, 255);
  background(224);
  smooth();

  pg1 = makeTexture(2);

  p = new Array(numP);
  for (i=0; i<numP; i++) {
    let a = new PVector(0.0, 0.0);
    let v = new PVector(0.0, 0.0);
    let l = new PVector(random(50, width-50), random(50, height-50));
    p[i] = new Particle(a, v, l);
    p[i].setLimit(5.0);
  }
}

function keyReleased() {
  p = new Array(numP);
  for (i=0; i<numP; i++) {
    var a = new PVector(0.0, 0.0);
    var v = new PVector(0.0, 0.0);
    var l = new PVector(random(50, width-50), random(50, height-50));
    p[i] = new Particle(a, v, l);
    let r = 64;
    let g = 128;
    let b = 192;
    p[i].setColor(color(r, g, b, 32));
    p[i].setLimit(5.0);
  }
}

function draw() {
  background(224);
  for (i=0; i<numP; i++) {
    p[i].addForce(getGravForce(p[i]));
    p[i].run();
  }
}

function getGravForce(p_) {
  let loc = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  let mass = 10.0;
  var g = 100;

  let dir = new PVector();
  dir = dir.sub(loc, p_.loc);
  let d = dir.mag();
  d = constrain(d, 5.0, 15.0);
  dir.normalize();
  let f = (g*mass*p_.mass)/(d*d);
  dir.mult(f);
  return dir;
}

function makeTexture(r) {
  let res = createGraphics(r, r, P2D);
  res.beginDraw();
  res.loadPixels();
    for ( x = 0; x < res.width; x++) {   
      for( y = 0; y < res.height; y++ ) {
        res.pixels[y*res.width+x] = color(128, 64, 64, 64);
      }
    }
  res.updatePixels();
  res.endDraw();

  return res;  
}

function drawStar( img, x, y ) {
   blend(img, 0, 0, img.width, img.height, int(x) - img.width/2, int(y) - img.height/2, img.width, img.height, SUBTRACT);
}

